import subprocess, os, shutil, pty, select, fcntl, termios, struct
def run(args, cwd="/workspace"):
    r = subprocess.run(args, capture_output=True, cwd=cwd)
    return r.stdout.decode(errors='replace'), r.stderr.decode(errors='replace'), r.returncode

def run_pty(args, cols=80):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, cols, 0, 0))
    env={**os.environ, "TERM": "xterm-256color"}
    p = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, cwd="/workspace", env=env)
    os.close(slave)
    output = b""
    while True:
        try:
            r,_,_ = select.select([master], [], [], 2)
            if r:
                data = os.read(master, 4096)
                if not data: break
                output += data
            else:
                if p.poll() is not None:
                    try:
                        while True:
                            r2,_,_ = select.select([master], [], [], 0.2)
                            if not r2: break
                            d = os.read(master, 4096)
                            if not d: break
                            output += d
                    except: pass
                    break
        except OSError:
            break
    try: os.close(master)
    except: pass
    p.wait(timeout=5)
    return output.decode(errors='replace')

