pub fn terminal_size() -> Option<(Width, Height)> {
    for fd in [1i32, 2i32] {
        let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
        let ret = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws as *mut _ as *mut libc::c_void as *mut _ ) };
        // Actually libc::ioctl signature: ioctl(fd, request, ...) variadic. Need to pass &mut ws as third arg.
        // The above cast is wrong. Use: libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws)
        // But libc::ioctl is variadic, need to call correctly.
        let _ = ret;
        if ret == 0 && ws.ws_col != 0 {
            return Some((Width(ws.ws_col), Height(ws.ws_row)));
        }
    }
    None
}
