enum Detail { Dev, Ino, Nlink, Typ, Perm, Oct, User, Uid, Group, Gid, Size, Blocks, Btime, Ctime, Mtime, Atime, Git }

fn parse_details(vals: &[String]) -> Vec<Detail> {
    let mut out: Vec<Detail> = Vec::new();
    let push = |out: &mut Vec<Detail>, d: Detail| {
        if let Some(pos) = out.iter().position(|x| *x == d) { out.remove(pos); }
