                for d in [Detail::Nlink, Detail::Typ, Detail::Perm, Detail::User, Detail::Group, Detail::Size, Detail::Mtime] { push(&mut out, d); }
            }
            "all" => {
                for d in [Detail::Dev, Detail::Ino, Detail::Nlink, Detail::Typ, Detail::Perm, Detail::Oct, Detail::User, Detail::Uid, Detail::Group, Detail::Gid, Detail::Size, Detail::Blocks, Detail::Btime, Detail::Ctime, Detail::Mtime, Detail::Atime, Detail::Git] { push(&mut out, d); }
            }
            "dev" => push(&mut out, Detail::Dev),
            "ino" => push(&mut out, Detail::Ino),
            "nlink" => push(&mut out, Detail::Nlink),
            "typ" => push(&mut out, Detail::Typ),
            "perm" => push(&mut out, Detail::Perm),
            "oct" => push(&mut out, Detail::Oct),
            "user" => push(&mut out, Detail::User),
            "uid" => push(&mut out, Detail::Uid),
            "group" => push(&mut out, Detail::Group),
            "gid" => push(&mut out, Detail::Gid),
            "size" => push(&mut out, Detail::Size),
            "blocks" => push(&mut out, Detail::Blocks),
