// ---------- helpers: stripping ----------
fn strip_display(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::new();
    let mut i = 0usize;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            if i + 1 >= chars.len() {
                out.push_str("</>");
                i += 1;
            } else if chars[i+1] == '<' {
                out.push('<');
                i += 2;
            } else {
                out.push('\\');
                i += 1;
            }
        } else if c == '<' {
            // find next '>'
            let mut j = i + 1;
            let mut found = None;
            while j < chars.len() {
                if chars[j] == '>' { found = Some(j); break; }
                j += 1;
            }
            if let Some(k) = found {
                i = k + 1;
            } else {
                break;
            }
        } else {
            out.push(c);
            i += 1;
        }
    }
    out
}

fn is_readme_like(prefix: &str, name: &str) -> bool {
    if name == prefix { return true; }
    if let Some(rest) = name.strip_prefix(prefix) {
        if let Some(c) = rest.chars().next() {
            return !(c.is_alphanumeric() || c == '_');
        }
    }
    false
}

fn file_importance(basename: &str) -> i8 {
    if basename == ".git" || basename == ".DS_Store" { return 0; }
    if basename == "src" { return 3; }
    if basename == "Cargo.lock" { return 1; }
    if basename.starts_with('.') { return 1; }
    if is_readme_like("README", basename) { return 4; }
    2
}

fn file_icon(basename: &str, ftype: FType) -> char {
    // name overrides
    // exact
    if basename == "src" { return '\u{f40d}'; }
    if basename == "Cargo.toml" { return '\u{f487}'; }
    if basename == "Cargo.lock" { return '\u{f456}'; }
    if basename == "Makefile" { return '\u{f070e}'; }
    if basename == ".gitignore" || basename == ".git" { return '\u{f02a2}'; }
    if basename == ".DS_Store" { return '\u{f179}'; }
    if basename == ".github" { return '\u{f408}'; }
    // prefix Dockerfile (simple prefix)
    if basename.starts_with("Dockerfile") { return '\u{f4b7}'; }
    // README / LICENSE / .env with readme-like rule
    if is_readme_like("README", basename) { return '\u{f02d}'; }
    if is_readme_like("LICENSE", basename) { return '\u{f495}'; }
    if is_readme_like(".env", basename) { return '\u{e22f}'; }
    // ext based (after last dot, case-sensitive lowercase)
    if let Some(pos) = basename.rfind('.') {
        let ext = &basename[pos+1..];
        match ext {
            "txt" => return '\u{e612}',
            "md" => return '\u{f48a}',
            "rs" => return '\u{e68b}',
            "sh" => return '\u{f489}',
            "json" | "toml" | "yaml" | "yml" => return '\u{e60b}',
            "ini" => return '\u{e615}',
            "jpg" | "jpeg" | "png" | "gif" | "svg" | "ico" | "webp" => return '\u{f02e9}',
            "avi" | "flv" | "mkv" | "mov" | "mp4" | "webm" => return '\u{f0567}',
            "flac" | "mp3" | "ogg" | "wav" => return '\u{f04c3}',
            _ => {}
        }
    }
    // type based
    match ftype {
        FType::Dir => '\u{f07b}',
        FType::Symlink => '\u{f0339}',
        FType::Fifo => '\u{f07e5}',
        FType::Socket => '\u{f07e8}',
        FType::Block => '\u{f02ca}',
        FType::Char => '\u{f1dd}',
        FType::File => ' ',
    }
}

fn file_suffix(ftype: FType) -> Option<char> {
    match ftype {
        FType::Dir => Some('/'),
        FType::Symlink => Some('@'),
        FType::Fifo => Some('|'),
        FType::Socket => Some('='),
        _ => None,
    }
}

fn ftype_of_metadata(md: &std::fs::Metadata) -> FType {
    let ft = md.file_type();
    if ft.is_dir() { return FType::Dir; }
    if ft.is_symlink() { return FType::Symlink; }
    if ft.is_fifo() { return FType::Fifo; }
    if ft.is_socket() { return FType::Socket; }
    if ft.is_block_device() { return FType::Block; }
    if ft.is_char_device() { return FType::Char; }
    FType::File
}

fn typ_char(ft: FType) -> char {
    match ft {
        FType::Dir => 'd',
        FType::Symlink => 'l',
        FType::Fifo => 'p',
        FType::Socket => 's',
        FType::Block => 'b',
        FType::Char => 'c',
        FType::File => 'f',
    }
}

fn typ_rank(ft: FType) -> u8 {
    match ft {
        FType::Dir => 0,
        FType::Symlink => 1,
        FType::Fifo => 2,
        FType::Socket => 3,
        FType::Block => 4,
        FType::Char => 5,
        FType::File => 6,
    }
}

fn cat_rank(ft: FType) -> u8 {
    match ft {
        FType::Dir => 0,
        _ => 1,
    }
}
