// ---------- user/group ----------
fn username_of(uid: u32) -> Option<String> {
    unsafe {
        let mut buf = vec![0u8; 16384];
        let mut res: *mut libc::passwd = std::ptr::null_mut();
        let mut pwd: libc::passwd = std::mem::zeroed();
        let r = libc::getpwuid_r(uid, &mut pwd, buf.as_mut_ptr() as *mut i8, buf.len(), &mut res);
        if r == 0 && !res.is_null() {
            let c = std::ffi::CStr::from_ptr(pwd.pw_name);
            return Some(c.to_string_lossy().into_owned());
        }
    }
    None
}
fn groupname_of(gid: u32) -> Option<String> {
    unsafe {
        let mut buf = vec![0u8; 16384];
        let mut res: *mut libc::group = std::ptr::null_mut();
        let mut grp: libc::group = std::mem::zeroed();
        let r = libc::getgrgid_r(gid, &mut grp, buf.as_mut_ptr() as *mut i8, buf.len(), &mut res);
        if r == 0 && !res.is_null() {
            let c = std::ffi::CStr::from_ptr(grp.gr_name);
            return Some(c.to_string_lossy().into_owned());
        }
    }
    None
}

// ---------- btime via statx ----------
#[allow(dead_code)]
fn btime_of(path: &Path) -> Option<(i64, u32)> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;
    let c = CString::new(path.as_os_str().as_bytes()).ok()?;
    unsafe {
        let mut stx: libc::statx = std::mem::zeroed();
        // AT_SYMLINK_NOFOLLOW | AT_NO_AUTOMOUNT? Use 0x100 (AT_SYMLINK_NOFOLLOW) to lstat-like (not follow)
        // libc::AT_SYMLINK_NOFOLLOW = 0x100
        let mask = libc::STATX_BTIME;
        let ret = libc::statx(libc::AT_FDCWD, c.as_ptr(), libc::AT_SYMLINK_NOFOLLOW, mask, &mut stx);
        if ret != 0 { return None; }
        if (stx.stx_mask as u32 & libc::STATX_BTIME as u32) == 0 { return None; }
        if stx.stx_btime.tv_sec == 0 && stx.stx_btime.tv_nsec == 0 { return None; }
        Some((stx.stx_btime.tv_sec as i64, stx.stx_btime.tv_nsec as u32))
    }
}

// ---------- time formatting (UTC) ----------
fn format_time(sec: i64) -> String {
    unsafe {
        let mut tm: libc::tm = std::mem::zeroed();
        let t = sec as libc::time_t;
        let r = libc::gmtime_r(&t, &mut tm);
        if r.is_null() {
            return String::new();
        }
        let year = tm.tm_year + 1900;
        let mon = tm.tm_mon; // 0-11
        let mday = tm.tm_mday;
        let hour24 = tm.tm_hour;
        let min = tm.tm_min;
        let month = match mon { 0=>"Jan",1=>"Feb",2=>"Mar",3=>"Apr",4=>"May",5=>"Jun",6=>"Jul",7=>"Aug",8=>"Sep",9=>"Oct",10=>"Nov",11=>"Dec", _=>"???" };
        let (h12, ap) = match hour24 {
            0 => (12, "am"),
            1..=11 => (hour24, "am"),
            12 => (12, "pm"),
            _ => (hour24-12, "pm"),
        };
        format!("{:04}-{}-{:02} {:02}:{:02}{}", year, month, mday, h12, min, ap)
