// ---------- size formatting ----------
fn format_size(size: u64, unit: Unit) -> (String, String) {
    match unit {
        Unit::None => (format!("{}", size), "B".to_string()),
        Unit::Binary => {
            let (v, u) = if size < 1024 { (size as f64, "B") }
            else if size < 1024*1024 { (size as f64 / 1024.0, "KiB") }
            else if size < 1024u64.pow(3) { (size as f64 / 1024f64.powi(2), "MiB") }
            else if size < 1024u64.pow(4) { (size as f64 / 1024f64.powi(3), "GiB") }
            else if size < 1024u64.pow(5) { (size as f64 / 1024f64.powi(4), "TiB") }
            else if size < 1024u64.pow(6) { (size as f64 / 1024f64.powi(5), "PiB") }
            else { (size as f64 / 1024f64.powi(6), "EiB") };
            (format!("{:.1}", v), u.to_string())
        }
        Unit::Decimal => {
            let (v, u) = if size < 1000 { (size as f64, "B") }
            else if size < 1000*1000 { (size as f64 / 1000.0, "kB") }
            else if size < 1000u64.pow(3) { (size as f64 / 1000f64.powi(2), "MB") }
            else if size < 1000u64.pow(4) { (size as f64 / 1000f64.powi(3), "GB") }
            else if size < 1000u64.pow(5) { (size as f64 / 1000f64.powi(4), "TB") }
            else if size < 1000u64.pow(6) { (size as f64 / 1000f64.powi(5), "PB") }
            else { (size as f64 / 1000f64.powi(6), "EB") };
            (format!("{:.1}", v), u.to_string())
        }
    }
}

// ---------- perm formatting ----------
fn format_perm(mode: u32) -> String {
    // mode & 0o7777, but display 9 chars with spaces: "rwx r-x r-x" etc., with s/S/t/T for special
    let suid = (mode & 0o4000) != 0;
    let sgid = (mode & 0o2000) != 0;
    let sticky = (mode & 0o1000) != 0;
    let mut s = String::new();
